<?php
if(empty($staff)||!isset($pdo)){http_response_code(403);exit;}
$reviewRows=[];$reviewCount=0;$reviewStats=['total'=>0,'average'=>null,'positive'=>0];$reviewPage=max(1,(int)($_GET['page']??1));
$reviewRating=filter_var($_GET['rating']??null,FILTER_VALIDATE_INT);if(!$reviewRating||$reviewRating<1||$reviewRating>5)$reviewRating=null;
$reviewSort=($_GET['sort']??'latest')==='lowest'?'lowest':'latest';$reviewLoadError=false;
try{
 $reviewStats=$pdo->query('SELECT COUNT(*) AS total,AVG(rating) AS average,COALESCE(SUM(rating>=4),0) AS positive FROM reviews')->fetch();
 $where=[];$parameters=[];
 if($search!==''){$where[]='(u.name LIKE ? OR u.email LIKE ? OR r.comment LIKE ?)';$parameters=array_fill(0,3,'%'.$search.'%');}
 if($reviewRating){$where[]='r.rating=?';$parameters[]=$reviewRating;}
 $clause=$where?' WHERE '.implode(' AND ',$where):'';
 $stmt=$pdo->prepare('SELECT COUNT(*) FROM reviews r JOIN users u ON u.id=r.user_id'.$clause);$stmt->execute($parameters);$reviewCount=(int)$stmt->fetchColumn();
 $reviewPage=min($reviewPage,max(1,(int)ceil($reviewCount/12)));
 $order=$reviewSort==='lowest'?'r.rating ASC,r.updated_at DESC,r.id DESC':'r.updated_at DESC,r.id DESC';
 $stmt=$pdo->prepare('SELECT r.id,r.rating,r.comment,r.created_at,r.updated_at,u.name,u.email FROM reviews r JOIN users u ON u.id=r.user_id'.$clause.' ORDER BY '.$order.' LIMIT 12 OFFSET '.(($reviewPage-1)*12));$stmt->execute($parameters);$reviewRows=$stmt->fetchAll();
}catch(Throwable $e){error_log($e->getMessage());$reviewLoadError=true;}
?>
<section class="review-admin-banner"><span class="review-admin-symbol" aria-hidden="true">✦</span><div><p class="eyebrow">LISTEN. LEARN. REFINE.</p><h2>Customer feedback, in focus.</h2><p>Read the experiences your customers share and spot opportunities to improve.</p></div><a href="index.php#reviews">View public reviews ↗</a></section>
<?php if($reviewLoadError): ?><p class="staff-error" role="alert">Customer reviews could not be loaded. Please refresh and try again.</p><?php else: ?>
<div class="review-admin-stats"><article><span>Total reviews</span><strong><?=h($reviewStats['total'])?></strong><small>One review per customer account</small></article><article><span>Average rating</span><strong><?= $reviewStats['average']!==null?h(number_format((float)$reviewStats['average'],1)).'<small> / 5</small>':'—'?></strong><small>Based on all published reviews</small></article><article><span>4 &amp; 5 star reviews</span><strong><?=h($reviewStats['positive'])?></strong><small>Positive customer ratings</small></article></div>
<section class="panel admin-review-panel"><div class="panel-title"><h2>Customer Reviews</h2><span class="pill"><?=$reviewCount?> <?=$reviewCount===1?'result':'results'?></span></div><form class="staff-filters review-admin-filters" method="get"><input type="hidden" name="view" value="reviews"><label>Search reviews<input name="q" maxlength="100" value="<?=h($search)?>" placeholder="Customer name, email or comment"></label><label>Rating<select name="rating"><option value="">All ratings</option><?php for($r=5;$r>=1;$r--): ?><option value="<?=$r?>" <?=$reviewRating===$r?'selected':''?>><?=$r?> <?=$r===1?'star':'stars'?></option><?php endfor; ?></select></label><label>Sort by<select name="sort"><option value="latest" <?=$reviewSort==='latest'?'selected':''?>>Recently updated</option><option value="lowest" <?=$reviewSort==='lowest'?'selected':''?>>Lowest rating first</option></select></label><button class="button">Apply filters ↗</button><a href="admin.php?view=reviews">Reset</a></form>
<?php if(!$reviewRows): ?><div class="review-admin-empty"><span aria-hidden="true">✎</span><h3><?=$reviewStats['total']?'No reviews match your filters.':'No customer reviews yet.'?></h3><p><?=$reviewStats['total']?'Try another search or reset the filters.':'Reviews submitted on the website or customer dashboard will appear here.'?></p></div><?php else: ?><div class="review-admin-grid"><?php foreach($reviewRows as $review): ?><article class="review-admin-card"><div class="review-admin-card-head"><span class="avatar small" aria-hidden="true"><?=h(function_exists('mb_substr')?mb_substr($review['name'],0,1):substr($review['name'],0,1))?></span><div><h3><?=h($review['name'])?></h3><span class="review-admin-email"><?=h($review['email'])?></span></div><span class="review-admin-score"><?=h($review['rating'])?> <span aria-hidden="true">★</span></span></div><div class="review-admin-stars" aria-label="<?=h($review['rating'])?> out of 5 stars"><span aria-hidden="true"><?=str_repeat('★',(int)$review['rating'])?><span><?=str_repeat('★',5-(int)$review['rating'])?></span></span></div><p class="review-admin-comment"><?=nl2br(h($review['comment']))?></p><div class="review-admin-card-foot"><span>Review #<?=h($review['id'])?></span><time datetime="<?=h(date('c',strtotime($review['updated_at'])))?>">Updated <?=h(date('d M Y',strtotime($review['updated_at'])))?></time></div></article><?php endforeach; ?></div><?php endif; ?>
<div class="pagination"><span>Page <?=$reviewPage?> of <?=max(1,(int)ceil($reviewCount/12))?></span><?php foreach(['Previous'=>$reviewPage-1,'Next'=>$reviewPage+1] as $label=>$p): if($p<1||$p>max(1,(int)ceil($reviewCount/12)))continue; ?><a href="admin.php?<?=h(http_build_query(['view'=>'reviews','page'=>$p,'q'=>$search,'rating'=>$reviewRating,'sort'=>$reviewSort]))?>"><?=$label?> →</a><?php endforeach; ?></div><p class="fine">Reviews are published by customers. Updated reviews appear here automatically when you refresh.</p></section><?php endif; ?>
